// import axios from "axios";
// import { BASE_URL } from "./config";

// const axios_api = axios.create({
//   baseURL: BASE_URL,
//   headers: {
//     "Content-Type": "application/json",
//   },
// });

// export default axios_api;


// axios.js (데모 전용 mock axios)
const fakeDB = {
  "/plan/itemlist/main": [
    { itemNo: 1, itemName: "데모 상품 A" },
    { itemNo: 2, itemName: "데모 상품 B" },
  ],

  // 예측 시리즈 (ForecastWithSelector 등에서 부르는 함수)
  // 실제 코드에서 params로 { itemNo, h } 넘기는 형태
  // itemNo=1,h=12 기준 더미
  "/forecast/series?itemNo=1&h=12": {
    itemNo: 1,
    horizon: 12,
    series: [
      { ym: "2025-01", qty: 120 },
      { ym: "2025-02", qty: 140 },
      { ym: "2025-03", qty: 160 },
    ],
  },

  // 매출 차트용 (ex: /sales/monthly?ym=2025-01)
  "/sales/monthly?ym=2025-01": [
    { ym: "2025-01", totalSales: 1230000 },
    { ym: "2025-02", totalSales: 1500000 },
    { ym: "2025-03", totalSales: 990000 },
  ],

  // top N 품목 수량
  "/sales/item-qty-monthly?ym=2025-01": [
    { itemName: "데모 상품 A", qty: 120 },
    { itemName: "데모 상품 B", qty: 95 },
    { itemName: "데모 상품 C", qty: 60 },
  ],

  // 월별 상품 전체 (드롭다운이나 테이블에서 사용)
  "/sales/item-qty-monthly-all": [
    { ym: "2025-01", itemName: "데모 상품 A", qty: 120 },
    { ym: "2025-01", itemName: "데모 상품 B", qty: 80 },
    { ym: "2025-02", itemName: "데모 상품 A", qty: 140 },
    { ym: "2025-02", itemName: "데모 상품 B", qty: 90 },
  ],
};

// 내부적으로 key를 만드는 유틸.
// path("/forecast/series") + opts.params({ itemNo:1, h:12 }) -> "/forecast/series?itemNo=1&h=12"
function buildKey(path, opts = {}) {
  if (!opts.params || typeof opts.params !== "object") {
    return path;
  }
  const query = Object.entries(opts.params)
    .map(([k, v]) => `${k}=${encodeURIComponent(v)}`)
    .join("&");
  return `${path}?${query}`;
}

// fakeDB에서 데이터 찾아오는 함수
function fakeDBKeyLookup(path, opts = {}) {
  const key = buildKey(path, opts);
  if (fakeDB.hasOwnProperty(key)) {
    return fakeDB[key];
  }

  // 못 찾은 경우. 기본값 반환.
  // 배열[]로, 차트 비어 있는 상태로만 보여줌.
  console.warn("[mock axios] no mock data for", key);
  return [];
}

// axios 비슷하게 보이도록 만들어주는 mock 클라이언트
const axios_api = {
  get: async (path, opts = {}) => {
    const data = fakeDBKeyLookup(path, opts);
    return { data };
  },
  post: async () => {
    return { data: { success: true } };
  },
  put: async () => {
    return { data: { success: true } };
  },
  delete: async () => {
    return { data: { success: true } };
  },
  patch: async () => {
    return { data: { success: true } };
  },
};

export default axios_api;
